import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Pb {

    private enum Zone {
        OUTSIDE, INSIDE
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int tam = Integer.parseInt(br.readLine());
        String cad = br.readLine();

        List<String> arr = new ArrayList<>();
        String word = "";
        int cont = 0;
        int mayor = 0;
        Zone zone = Zone.OUTSIDE;

        for (int i = 0; i < tam; i++) {
            char c = cad.charAt(i);

            if (c == '(') {
                if (cont >= mayor) {
                    mayor = cont;
                }
                cont = 0;
                zone = Zone.INSIDE;
            } else if (c == ')') {
                zone = Zone.OUTSIDE;
                if (!word.isEmpty()) {
                    arr.add(word);
                    word = "";
                }
            } else if (zone == Zone.INSIDE) {
                if (c != '_') {
                    word += c;
                } else if (!word.isEmpty()) {
                    arr.add(word);
                    word = "";
                }
            } else if (c != '_') {
                cont++;
                if (i == tam - 1 && cont >= mayor) {
                    mayor = cont;
                }
            } else {
                if (cont >= mayor) {
                    mayor = cont;
                }
                cont = 0;
            }
        }

        System.out.println(mayor + " " + arr.size());
    }
}
